const out = items[0].json;
const ok  = out.exitCode === 0;
const log = (out.stdout || '').slice(-400);
console.log('[Météo]', ok ? 'OK' : 'ERREUR', log);
return [{ json: { step: 'meteo', success: ok, exitCode: out.exitCode, preview: log } }];

const UNIT_MAP = { pm25:'µg/m³', pm10:'µg/m³', no2:'µg/m³', o3:'µg/m³', co:'mg/m³', so2:'µg/m³' };
const lastLine = Number($node['4. IoT Silver – Lire curseur'].json.last_line || 0);
const content  = items[0].json.stdout || '';
const lines    = content.split('\n');
const out = [];
for (let i = lastLine; i < lines.length; i++) {
  const t = lines[i].trim();
  if (!t) continue;
  try {
    const row = JSON.parse(t);
    const v = Number(row.value);
    if (Number.isNaN(v) || v < 0 || v > 500) continue;
    const dt = new Date(row.datetime_utc);
    if (isNaN(dt.getTime())) continue;
    const pol = (row.pollutant || 'unknown').toLowerCase();
    out.push({ json: {
      sensor_id: row.sensor_id, location_id: row.location_id || null,
      sensor_name: row.sensor_name || null, city: row.city || null,
      latitude: row.latitude != null ? Number(row.latitude) : null,
      longitude: row.longitude != null ? Number(row.longitude) : null,
      pollutant: pol, value: v,
      unit: UNIT_MAP[pol] || row.unit || 'unknown',
      datetime_utc: dt.toISOString(), source: row.source || 'OpenAQ',
      _new_last_line: i + 1 === lines.length ? lines.length : null
    }});
  } catch(e) {}
}
if (out.length > 0) out[out.length-1].json._new_last_line = lines.length;
return out;

